// Natural sort comparison
fn split_natural(s: &str) -> Vec<String> {
    // split into digit/non-digit chunks
    let mut chunks = Vec::new();
    let mut cur = String::new();
    let mut cur_is_digit: Option<bool> = None;
    for c in s.chars() {
        let is_d = c.is_ascii_digit();
        match cur_is_digit {
            None => { cur.push(c); cur_is_digit = Some(is_d); }
            Some(d) if d == is_d => { cur.push(c); }
            Some(_) => { chunks.push(cur); cur = String::new(); cur.push(c); cur_is_digit = Some(is_d); }
        }
    }
    if !cur.is_empty() { chunks.push(cur); }
    chunks
}

fn has_leading_zero(s: &str) -> bool {
    s.len() > 1 && s.starts_with('0')
}

fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let ca = split_natural(a);
    let cb = split_natural(b);
    let n = ca.len().min(cb.len());
    for i in 0..n {
        let xa = &ca[i];
        let xb = &cb[i];
        let a_digit = xa.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
        let b_digit = xb.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
        if a_digit && b_digit {
            let a_lz = has_leading_zero(xa);
            let b_lz = has_leading_zero(xb);
            if a_lz || b_lz {
                // lexical
                match xa.cmp(xb) {
                    std::cmp::Ordering::Equal => continue,
                    o => return o,
                }
            } else {
                // numeric: first by length, then lexical
                if xa.len() != xb.len() {
                    return xa.len().cmp(&xb.len());
                }
                match xa.cmp(xb) {
                    std::cmp::Ordering::Equal => continue,
                    o => return o,
                }
            }
        } else {
            match xa.cmp(xb) {
                std::cmp::Ordering::Equal => continue,
                o => return o,
            }
        }
    }
    ca.len().cmp(&cb.len())
}

// Extension: from file name (after last slash), find last dot
fn get_extension(path: &str) -> String {
    if path.is_empty() { return String::new(); }
    // file name after last slash
    let fname = match path.rfind('/') {
        Some(i) => &path[i+1..],
        None => path,
    };
    if fname.is_empty() { return String::new(); }
    match fname.rfind('.') {
        None => String::new(),
        Some(0) => {
            // dot at start: if only one dot at start, no ext; else ext from last dot?
            // e.g., ".hidden" => no ext, ".hidden.txt" => ".txt"
            // Since rfind gives last dot, if last dot is at 0, then no ext
            // else ext
            // For ".hidden", last dot at 0 => no ext
            // For ".hidden.txt", last dot not at 0 => ext
            // Our match gives pos 0 only if last dot is at 0, so no ext
            String::new()
        }
        Some(pos) => {
            fname[pos..].to_string()
        }
    }
}

// Placeholder expansion
#[derive(Debug)]
enum Token {
    Lit(String),
    Ph { group: String, padding: Option<String>, auto_idx: Option<usize> }, // auto_idx set later? Actually group empty means auto, need index
}

fn parse_output_pattern(pat: &str) -> Result<Vec<Token>, String> {
    let mut tokens: Vec<Token> = Vec::new();
    let mut lit = String::new();
    let bytes = pat.as_bytes();
    let chars: Vec<char> = pat.chars().collect();
    // need byte index for error positions? Use char index? For ASCII same. Use byte index via char_indices?
    // We'll use byte position via char_indices
    let mut i = 0;
    let mut auto_counter = 0usize; // for assigning? Actually we need to count autos to assign indices later? We'll store placeholder with group string, and later resolve autos.
    // Instead, parse and keep group string, padding string. Autos will be resolved during expansion per file (counting autos in order).
    // So just store.
    let mut idx = 0; // byte index
    let char_indices: Vec<(usize, char)> = pat.char_indices().collect();
    let mut ci = 0;
    while ci < char_indices.len() {
        let (bpos, c) = char_indices[ci];
        if c == '\\' {
            // check next
            if ci + 1 >= char_indices.len() {
                // trailing \ ignored (drop)
                ci += 1;
                continue;
            }
            let (_, nc) = char_indices[ci+1];
            if nc == '{' || nc == '}' || nc == '\\' {
                lit.push(nc);
                ci += 2;
            } else {
                return Err(format!("invalid escape character of '{}' at '{}'", nc, char_indices[ci+1].0));
            }
        } else if c == '{' {
            // find next '}'
            // search for next unescaped '}'? Since escapes only outside? Inside placeholder, just find next '}' char
            let mut found: Option<usize> = None; // index in char_indices
            let mut j = ci + 1;
            while j < char_indices.len() {
                if char_indices[j].1 == '}' {
                    // check if escaped? Inside placeholder, escapes? The pattern "\\}" outside would have been handled as escape, but inside placeholder content, a '\' before '}'? Unclear. Simplify: find next '}' regardless (since placeholder content cannot contain escaped braces? Actually content could contain '{', but '}' ends)
                    // Need to handle escaped '}' inside? E.g., pattern "{a\\}b}"? Unlikely. We'll just find next '}'.
                    found = Some(j);
                    break;
                }
                j += 1;
            }
            if found.is_none() {
                return Err(format!("all opened placeholders must be closed by '}}'"));
            }
            let j = found.unwrap();
            // content between ci+1 .. j
            let content: String = char_indices[ci+1..j].iter().map(|(_,c)| *c).collect();
            // split on first ':'
            let (g, p) = match content.find(':') {
                None => (content, None),
                Some(pos) => {
                    let (gg, pp) = content.split_at(pos);
                    let pp = &pp[1..]; // skip ':'
                    // check if pp contains ':' -> invalid padding
                    if pp.contains(':') {
                        return Err(format!("unable to parse padding of '{}'", pp));
                    }
                    (gg.to_string(), Some(pp.to_string()))
                }
            };
            // validate padding: must be empty or all digits
            if let Some(ref pp) = p {
                if !pp.is_empty() && !pp.chars().all(|c| c.is_ascii_digit()) {
                    return Err(format!("unable to parse padding of '{}'", pp));
                }
            }
            // flush lit
            if !lit.is_empty() {
                tokens.push(Token::Lit(lit.clone()));
                lit.clear();
            }
            tokens.push(Token::Ph { group: g, padding: p, auto_idx: None });
            ci = j + 1;
        } else if c == '}' {
            return Err(format!("an unopened placeholder could not be closed by '}}'"));
        } else {
            lit.push(c);
            ci += 1;
        }
    }
    if !lit.is_empty() {
        tokens.push(Token::Lit(lit));
    }
    Ok(tokens)
}

fn resolve_group_sort(group: &str, auto_val: usize, filename: &str, enumerator: usize) -> String {
    let g = if group.is_empty() {
        auto_val.to_string()
    } else {
        group.to_string()
    };
    // try parse as usize
    if let Ok(n) = g.parse::<usize>() {
        if n == 0 {
            return filename.to_string();
        } else if n == 1 {
            return enumerator.to_string();
        } else {
            return String::new();
        }
    } else {
        // named or invalid -> empty for sort
        // Note: auto_val is already numeric string? Actually for auto, g is auto_val string (numeric), so it will be parsed above.
        // For explicit non-numeric, empty.
        return String::new();
    }
}

fn resolve_group_regex(group: &str, auto_val: usize, caps: &regex::Captures, names: &std::collections::HashMap<String, usize>) -> String {
    let g = if group.is_empty() {
        auto_val.to_string()
    } else {
        group.to_string()
    };
    if let Ok(n) = g.parse::<usize>() {
        // numeric
        if let Some(m) = caps.get(n) {
            return m.as_str().to_string();
        } else {
            return String::new();
        }
    } else {
        // named
        if let Some(m) = caps.name(&g) {
            return m.as_str().to_string();
        } else {
            return String::new();
        }
    }
}

fn apply_padding(s: &str, padding: &Option<String>) -> String {
    if let Some(p) = padding {
        if p.is_empty() {
            return s.to_string();
        }
        // parse width
        let width: usize = p.parse().unwrap_or(0);
        if width == 0 {
            return s.to_string();
        }
        // check if s is all digits and not empty
        if !s.is_empty() && s.chars().all(|c| c.is_ascii_digit()) {
            if s.len() >= width {
                return s.to_string();
            } else {
                let mut res = String::new();
                for _ in 0..(width - s.len()) {
                    res.push('0');
                }
                res.push_str(s);
                return res;
            }
        } else {
            return s.to_string();
        }
    } else {
        return s.to_string();
    }
}

fn expand_sort(tokens: &[Token], filename: &str, enumerator: usize) -> String {
    let mut auto_counter = 1usize;
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Lit(s) => out.push_str(s),
            Token::Ph { group, padding, .. } => {
                let auto_val = if group.is_empty() {
                    let v = auto_counter;
                    auto_counter += 1;
                    v
                } else { 0 }; // dummy
                let raw = if group.is_empty() {
                    // auto
                    resolve_group_sort("", auto_val, filename, enumerator)
                } else {
                    resolve_group_sort(group, 0, filename, enumerator)
                };
                let padded = apply_padding(&raw, padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

fn expand_regex(tokens: &[Token], caps: &regex::Captures) -> String {
    let mut auto_counter = 1usize;
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Lit(s) => out.push_str(s),
            Token::Ph { group, padding, .. } => {
                let auto_val = if group.is_empty() {
                    let v = auto_counter;
                    auto_counter += 1;
                    v
                } else { 0 };
                let raw = if group.is_empty() {
                    // auto numeric
                    if let Some(m) = caps.get(auto_val) {
                        m.as_str().to_string()
                    } else {
                        String::new()
                    }
                } else {
                    // try numeric
                    if let Ok(n) = group.parse::<usize>() {
                        if let Some(m) = caps.get(n) {
                            m.as_str().to_string()
                        } else {
                            String::new()
                        }
                    } else {
                        if let Some(m) = caps.name(group) {
                            m.as_str().to_string()
                        } else {
                            String::new()
                        }
                    }
                };
                let padded = apply_padding(&raw, padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

fn print_table(rows: &[(String,String)]) {
    if rows.is_empty() {
        return;
    }
    // rows already sorted by output?
    let mut input_w = "Input".chars().count();
    let mut output_w = "Output".chars().count();
    for (a,b) in rows {
        input_w = input_w.max(a.chars().count());
        output_w = output_w.max(b.chars().count());
    }
    let line = format!("+{}+{}+", "-".repeat(input_w+2), "-".repeat(output_w+2));
    println!("{}", line);
    println!("| {:<input_w$} | {:<output_w$} |", "Input", "Output", input_w=input_w, output_w=output_w);
    println!("{}", line);
    for (a,b) in rows {
        println!("| {:<input_w$} | {:<output_w$} |", a, b, input_w=input_w, output_w=output_w);
    }
    println!("{}", line);
}

