// Natural sort comparison
fn split_natural(s: &str) -> Vec<String> {
    // split into digit/non-digit chunks
    let mut chunks = Vec::new();
    let mut cur = String::new();
    let mut cur_is_digit: Option<bool> = None;
    for c in s.chars() {
        let is_d = c.is_ascii_digit();
        match cur_is_digit {
            None => { cur.push(c); cur_is_digit = Some(is_d); }
            Some(d) if d == is_d => { cur.push(c); }
            Some(_) => { chunks.push(cur); cur = String::new(); cur.push(c); cur_is_digit = Some(is_d); }
        }
    }
    if !cur.is_empty() { chunks.push(cur); }
    chunks
}

fn has_leading_zero(s: &str) -> bool {
    s.len() > 1 && s.starts_with('0')
}

fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    let ca = split_natural(a);
    let cb = split_natural(b);
    let n = ca.len().min(cb.len());
    for i in 0..n {
        let xa = &ca[i];
        let xb = &cb[i];
        let a_digit = xa.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
        let b_digit = xb.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
        if a_digit && b_digit {
            let a_lz = has_leading_zero(xa);
            let b_lz = has_leading_zero(xb);
            if a_lz || b_lz {
                // lexical
                match xa.cmp(xb) {
                    std::cmp::Ordering::Equal => continue,
                    o => return o,
                }
            } else {
                // numeric: first by length, then lexical
                if xa.len() != xb.len() {
                    return xa.len().cmp(&xb.len());
                }
                match xa.cmp(xb) {
                    std::cmp::Ordering::Equal => continue,
                    o => return o,
                }
            }
        } else {
            match xa.cmp(xb) {
                std::cmp::Ordering::Equal => continue,
                o => return o,
            }
        }
    }
    ca.len().cmp(&cb.len())
}

// Extension: from file name (after last slash), find last dot
fn get_extension(path: &str) -> String {
    if path.is_empty() { return String::new(); }
    // file name after last slash
    let fname = match path.rfind('/') {
        Some(i) => &path[i+1..],
        None => path,
    };
    if fname.is_empty() { return String::new(); }
    match fname.rfind('.') {
        None => String::new(),
        Some(0) => {
            // dot at start: if only one dot at start, no ext; else ext from last dot?
            // e.g., ".hidden" => no ext, ".hidden.txt" => ".txt"
            // Since rfind gives last dot, if last dot is at 0, then no ext
            // else ext
            // For ".hidden", last dot at 0 => no ext
            // For ".hidden.txt", last dot not at 0 => ext
            // Our match gives pos 0 only if last dot is at 0, so no ext
            String::new()
        }
        Some(pos) => {
            fname[pos..].to_string()
        }
    }
}

