fn prepend_underscore(p: &str) -> String {
    match p.rfind('/') {
        Some(idx) => {
            let (dir, file) = p.split_at(idx+1);
            format!("{}_{}", dir, file)
        }
        None => format!("_{}", p),
    }
}
