                    // Need to handle escaped '}' inside? E.g., pattern "{a\\}b}"? Unlikely. We'll just find next '}'.
                    found = Some(j);
                    break;
                }
                j += 1;
            }
            if found.is_none() {
                return Err(format!("all opened placeholders must be closed by '}}'"));
            }
            let j = found.unwrap();
            // content between ci+1 .. j
            let content: String = char_indices[ci+1..j].iter().map(|(_,c)| *c).collect();
            // split on first ':'
            let (g, p) = match content.find(':') {
                None => (content, None),
                Some(pos) => {
                    let (gg, pp) = content.split_at(pos);
                    let pp = &pp[1..]; // skip ':'
                    // check if pp contains ':' -> invalid padding
                    if pp.contains(':') {
                        return Err(format!("unable to parse padding of '{}'", pp));
                    }
                    (gg.to_string(), Some(pp.to_string()))
                }
            };
            // validate padding: must be empty or all digits
            if let Some(ref pp) = p {
                if !pp.is_empty() && !pp.chars().all(|c| c.is_ascii_digit()) {
                    return Err(format!("unable to parse padding of '{}'", pp));
                }
            }
            // flush lit
            if !lit.is_empty() {
                tokens.push(Token::Lit(lit.clone()));
                lit.clear();
            }
            tokens.push(Token::Ph { group: g, padding: p, auto_idx: None });
            ci = j + 1;
        } else if c == '}' {
            return Err(format!("an unopened placeholder could not be closed by '}}'"));
        } else {
            lit.push(c);
            ci += 1;
        }
    }
    if !lit.is_empty() {
        tokens.push(Token::Lit(lit));
    }
    Ok(tokens)
}

fn resolve_group_sort(group: &str, auto_val: usize, filename: &str, enumerator: usize) -> String {
    let g = if group.is_empty() {
        auto_val.to_string()
    } else {
        group.to_string()
    };
    // try parse as usize
    if let Ok(n) = g.parse::<usize>() {
        if n == 0 {
            return filename.to_string();
        } else if n == 1 {
            return enumerator.to_string();
        } else {
            return String::new();
        }
    } else {
        // named or invalid -> empty for sort
        // Note: auto_val is already numeric string? Actually for auto, g is auto_val string (numeric), so it will be parsed above.
        // For explicit non-numeric, empty.
        return String::new();
    }
}

fn resolve_group_regex(group: &str, auto_val: usize, caps: &regex::Captures, names: &std::collections::HashMap<String, usize>) -> String {
    let g = if group.is_empty() {
        auto_val.to_string()
    } else {
        group.to_string()
    };
    if let Ok(n) = g.parse::<usize>() {
        // numeric
        if let Some(m) = caps.get(n) {
            return m.as_str().to_string();
        } else {
            return String::new();
        }
    } else {
        // named
        if let Some(m) = caps.name(&g) {
            return m.as_str().to_string();
        } else {
            return String::new();
        }
    }
}

fn apply_padding(s: &str, padding: &Option<String>) -> String {
    if let Some(p) = padding {
        if p.is_empty() {
            return s.to_string();
        }
        // parse width
        let width: usize = p.parse().unwrap_or(0);
        if width == 0 {
            return s.to_string();
        }
        // check if s is all digits and not empty
        if !s.is_empty() && s.chars().all(|c| c.is_ascii_digit()) {
            if s.len() >= width {
                return s.to_string();
            } else {
                let mut res = String::new();
                for _ in 0..(width - s.len()) {
                    res.push('0');
                }
                res.push_str(s);
                return res;
            }
        } else {
            return s.to_string();
        }
    } else {
        return s.to_string();
    }
}

fn expand_sort(tokens: &[Token], filename: &str, enumerator: usize) -> String {
    let mut auto_counter = 1usize;
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Lit(s) => out.push_str(s),
            Token::Ph { group, padding, .. } => {
                let auto_val = if group.is_empty() {
                    let v = auto_counter;
                    auto_counter += 1;
                    v
                } else { 0 }; // dummy
                let raw = if group.is_empty() {
                    // auto
                    resolve_group_sort("", auto_val, filename, enumerator)
                } else {
                    resolve_group_sort(group, 0, filename, enumerator)
                };
                let padded = apply_padding(&raw, padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

fn expand_regex(tokens: &[Token], caps: &regex::Captures) -> String {
    let mut auto_counter = 1usize;
    let mut out = String::new();
    for tok in tokens {
        match tok {
            Token::Lit(s) => out.push_str(s),
            Token::Ph { group, padding, .. } => {
                let auto_val = if group.is_empty() {
                    let v = auto_counter;
                    auto_counter += 1;
                    v
                } else { 0 };
                let raw = if group.is_empty() {
                    // auto numeric
                    if let Some(m) = caps.get(auto_val) {
                        m.as_str().to_string()
                    } else {
                        String::new()
                    }
                } else {
                    // try numeric
                    if let Ok(n) = group.parse::<usize>() {
                        if let Some(m) = caps.get(n) {
                            m.as_str().to_string()
                        } else {
                            String::new()
                        }
                    } else {
                        if let Some(m) = caps.name(group) {
                            m.as_str().to_string()
                        } else {
                            String::new()
                        }
                    }
                };
                let padded = apply_padding(&raw, padding);
                out.push_str(&padded);
            }
        }
    }
    out
}

fn print_table(rows: &[(String,String)]) {
    if rows.is_empty() {
        return;
    }
    // rows already sorted by output?
    let mut input_w = "Input".chars().count();
    let mut output_w = "Output".chars().count();
    for (a,b) in rows {
        input_w = input_w.max(a.chars().count());
        output_w = output_w.max(b.chars().count());
    }
    let line = format!("+{}+{}+", "-".repeat(input_w+2), "-".repeat(output_w+2));
    println!("{}", line);
    println!("| {:<input_w$} | {:<output_w$} |", "Input", "Output", input_w=input_w, output_w=output_w);
    println!("{}", line);
    for (a,b) in rows {
        println!("| {:<input_w$} | {:<output_w$} |", a, b, input_w=input_w, output_w=output_w);
    }
    println!("{}", line);
}

