                    }
                }
                successes.sort_by(|a,b| a.1.cmp(&b.1));
                if !quiet_flag && !successes.is_empty() {
                    print_table(&successes);
                }
                for e in errors { eprintln!("{}", e); }
                if !errors.is_empty() { std::process::exit(1); }
            }
        }
    }
}

fn prepend_underscore(p: &str) -> String {
    match p.rfind('/') {
        Some(idx) => {
            let (dir, file) = p.split_at(idx+1);
            format!("{}_{}", dir, file)
        }
        None => format!("_{}", p),
    }
}
